<?php
namespace App\Models\Ledger;use PDO;
class TaxFinancialStatementModel{
 public function __construct(private readonly PDO$db){}public function list(array$f=[]):array{$sql="SELECT h.*,c.company_name_ko company_name,COUNT(l.id) line_count,COALESCE(SUM(l.current_amount),0) current_total FROM ledger_tax_financial_statements h JOIN system_company c ON c.id=h.company_id LEFT JOIN ledger_tax_financial_statement_lines l ON l.tax_financial_statement_id=h.id WHERE 1=1";$p=[];foreach(['company_id','report_type_code']as$k)if(($f[$k]??'')!==''){$sql.=" AND h.$k=:$k";$p[":$k"]=$f[$k];}if(($f['fiscal_year']??'')!==''){$sql.=' AND h.fiscal_year=:fiscal_year';$p[':fiscal_year']=(int)$f['fiscal_year'];}$sql.=' GROUP BY h.id,c.company_name_ko ORDER BY h.fiscal_year DESC,h.report_type_code';$q=$this->db->prepare($sql);$q->execute($p);return$q->fetchAll(PDO::FETCH_ASSOC)?:[];}public function find(string$id,bool$lock=false):?array{$q=$this->db->prepare('SELECT h.*,c.company_name_ko company_name FROM ledger_tax_financial_statements h JOIN system_company c ON c.id=h.company_id WHERE h.id=:id'.($lock?' FOR UPDATE':''));$q->execute([':id'=>$id]);return$q->fetch(PDO::FETCH_ASSOC)?:null;}public function duplicate(string$c,int$y,string$t):?array{$q=$this->db->prepare('SELECT * FROM ledger_tax_financial_statements WHERE company_id=:c AND fiscal_year=:y AND report_type_code=:t');$q->execute([':c'=>$c,':y'=>$y,':t'=>$t]);return$q->fetch(PDO::FETCH_ASSOC)?:null;}public function lines(string$id):array{$q=$this->db->prepare('SELECT l.*,a.account_code,a.account_name FROM ledger_tax_financial_statement_lines l LEFT JOIN ledger_accounts a ON a.id=l.account_id WHERE l.tax_financial_statement_id=:id ORDER BY l.sort_no,l.id');$q->execute([':id'=>$id]);return$q->fetchAll(PDO::FETCH_ASSOC)?:[];}public function insert(array$r):void{$this->run('INSERT INTO ledger_tax_financial_statements(id,company_id,fiscal_year,report_type_code,source_organization,filing_date,status_code,note,created_at,created_by,updated_at,updated_by) VALUES(:id,:company_id,:fiscal_year,:report_type_code,:source_organization,:filing_date,:status_code,:note,:created_at,:created_by,:updated_at,:updated_by)',$r);}public function update(string$id,array$r):void{$r[':id']=$id;$this->run('UPDATE ledger_tax_financial_statements SET company_id=:company_id,fiscal_year=:fiscal_year,report_type_code=:report_type_code,source_organization=:source_organization,filing_date=:filing_date,note=:note,updated_at=:updated_at,updated_by=:updated_by WHERE id=:id',$r);}public function replaceLines(string$id,array$rows):void{$this->run('DELETE FROM ledger_tax_financial_statement_lines WHERE tax_financial_statement_id=:id',[':id'=>$id]);foreach($rows as$r)$this->run('INSERT INTO ledger_tax_financial_statement_lines(id,tax_financial_statement_id,sort_no,item_code,item_name,account_id,hierarchy_level,current_amount,prior_amount,note,created_at,created_by,updated_at,updated_by) VALUES(:id,:parent,:sort_no,:item_code,:item_name,:account_id,:hierarchy_level,:current_amount,:prior_amount,:note,:created_at,:created_by,:updated_at,:updated_by)',$r+[':parent'=>$id]);}public function confirm(string$id,bool$yes,string$a,string$at):void{$this->run('UPDATE ledger_tax_financial_statements SET status_code=:s,confirmed_at=:ca,confirmed_by=:cb,updated_at=:ua,updated_by=:ub WHERE id=:id',[':s'=>$yes?'CONFIRMED':'DRAFT',':ca'=>$yes?$at:null,':cb'=>$yes?$a:null,':ua'=>$at,':ub'=>$a,':id'=>$id]);}public function delete(string$id):void{$this->run('DELETE FROM ledger_tax_financial_statements WHERE id=:id',[':id'=>$id]);}public function companies():array{return$this->db->query('SELECT id,company_name_ko name FROM system_company ORDER BY company_name_ko')->fetchAll(PDO::FETCH_ASSOC)?:[];}public function accounts():array{return$this->db->query('SELECT id,CONCAT(account_code,\' \',account_name) name FROM ledger_accounts WHERE deleted_at IS NULL AND is_posting=1 ORDER BY account_code')->fetchAll(PDO::FETCH_ASSOC)?:[];}private function run(string$s,array$p):void{$q=$this->db->prepare($s);$q->execute($p);}}
